/// All drawing instruction types
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum DrawingInstruction {
    Point(PointInstruction),
    Line(LineInstruction),
    Area(AreaInstruction),
    Text(TextInstruction),
}

impl DrawingInstruction {
    pub fn priority(&self) -> DisplayPriority {
        match self {
            DrawingInstruction::Point(i) => i.priority,
            DrawingInstruction::Line(i) => i.priority,
            DrawingInstruction::Area(i) => i.priority,
            DrawingInstruction::Text(i) => i.priority,
        }
    }

    pub fn viewing_group(&self) -> ViewingGroup {
        match self {
            DrawingInstruction::Point(i) => i.viewing_group,
            DrawingInstruction::Line(i) => i.viewing_group,
            DrawingInstruction::Area(i) => i.viewing_group,
            DrawingInstruction::Text(i) => i.viewing_group,
        }
    }

    pub fn feature_id(&self) -> Option<i64> {
        match self {
            DrawingInstruction::Point(i) => i.feature_id,
            DrawingInstruction::Line(i) => i.feature_id,
            DrawingInstruction::Area(i) => i.feature_id,
            DrawingInstruction::Text(i) => i.feature_id,
        }
    }

    pub fn scale_range(&self) -> ScaleRange {
        match self {
            DrawingInstruction::Point(i) => i.scale_range,
            DrawingInstruction::Line(i) => i.scale_range,
            DrawingInstruction::Area(i) => i.scale_range,
            DrawingInstruction::Text(i) => i.scale_range,
        }
    }

    pub fn display_plane(&self) -> DisplayPlane {
        match self {
            DrawingInstruction::Point(i) => i.display_plane,
            DrawingInstruction::Line(i) => i.display_plane,
            DrawingInstruction::Area(i) => i.display_plane,
            DrawingInstruction::Text(i) => i.display_plane,
        }
    }

    /// Get geometry type for S-101 render ordering
    pub fn geometry_type(&self) -> GeometryType {
        match self {
            DrawingInstruction::Area(_) => GeometryType::Area,
            DrawingInstruction::Line(_) => GeometryType::Line,
            DrawingInstruction::Point(_) => GeometryType::Point,
            DrawingInstruction::Text(_) => GeometryType::Text,
        }
    }

    /// Get S-101 compliant render order key
    /// Used for sorting: lower values rendered first (background)
    pub fn render_order(&self) -> RenderOrder {
        let order = RenderOrder::new(self.priority(), self.geometry_type(), self.feature_id())
            .with_render_category(self.viewing_group().0);
        // For area features, sort by bounding box extent (larger areas first = background)
        if let DrawingInstruction::Area(area) = self {
            let (mut x0, mut y0, mut x1, mut y1) = (f64::MAX, f64::MAX, f64::MIN, f64::MIN);
            for p in &area.exterior {
                if p.x < x0 {
                    x0 = p.x;
                }
                if p.y < y0 {
                    y0 = p.y;
                }
                if p.x > x1 {
                    x1 = p.x;
                }
                if p.y > y1 {
                    y1 = p.y;
                }
            }
            let extent = (x1 - x0) * (y1 - y0);
            return order.with_extent(extent);
        }
        order
    }

    /// Remap resolved colors using a token-to-color lookup function.
    /// Used for color profile switch (Day/Dusk/Night) without re-running Lua.
    pub fn remap_colors(&mut self, lookup: &dyn Fn(&str) -> Color) {
        match self {
            DrawingInstruction::Area(area) => {
                if let Some(token) = &area.fill_color_token {
                    if let AreaFillType::Solid(ref mut color) = area.fill {
                        *color = lookup(token);
                    }
                }
                if let Some(token) = &area.hatch_color_token {
                    if let AreaFillType::HatchFill { ref mut color, .. } = area.fill {
                        *color = lookup(token);
                    }
                }
                if let Some(ref mut outline) = area.outline {
                    if let Some(token) = &outline.color_token {
                        outline.color = lookup(token);
                    }
                }
            }
            DrawingInstruction::Line(line) => {
                if let Some(token) = &line.color_token {
                    line.style.color = lookup(token);
                }
            }
            DrawingInstruction::Text(text) => {
                if let Some(token) = &text.color_token {
                    text.color = lookup(token);
                }
            }
            DrawingInstruction::Point(_) => {
                // Point symbols use SVG rendering with color overrides;
                // handled by clearing symbol_cache on profile switch
            }
        }
    }
}

/// Collection of drawing instructions for a feature
#[derive(Debug, Clone, Default)]
pub struct FeatureInstructions {
    pub instructions: Vec<DrawingInstruction>,
}

impl FeatureInstructions {
    pub fn new() -> Self {
        FeatureInstructions {
            instructions: Vec::new(),
        }
    }

    pub fn add_point(&mut self, instruction: PointInstruction) {
        self.instructions
            .push(DrawingInstruction::Point(instruction));
    }

    pub fn add_line(&mut self, instruction: LineInstruction) {
        self.instructions
            .push(DrawingInstruction::Line(instruction));
    }

    pub fn add_area(&mut self, instruction: AreaInstruction) {
        self.instructions
            .push(DrawingInstruction::Area(instruction));
    }

    pub fn add_text(&mut self, instruction: TextInstruction) {
        self.instructions
            .push(DrawingInstruction::Text(instruction));
    }

    pub fn is_empty(&self) -> bool {
        self.instructions.is_empty()
    }

    pub fn len(&self) -> usize {
        self.instructions.len()
    }

    /// Sort by display priority
    pub fn sort_by_priority(&mut self) {
        self.instructions.sort_by_key(|i| i.priority());
    }
}
